INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c8ad-75d4-975b-4ffb2d5f4e49'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'Solve x/8 - (3x - 2)/5 = 2.', 'x = -64/19', 'Multiply by 40: 5x - 8(3x - 2) = 80. Hence, 5x - 24x + 16 = 80, so -19x = 64 and x = -64/19.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.045Z'::timestamptz, '2026-08-15T07:50:40.045Z'::timestamptz) ON CONFLICT (id) DO NOTHING;